SELECT `INFO_SYS`.`관리번호`, `INFO_SYS`.`IP_Adress`, `IP`.`호관` 
FROM `INFO_SYS` 
JOIN `IP` ON `INFO_SYS`.`IP_Adress` = `IP`.`IP`;

SELECT COUNT(*) FROM INFO_SYS 
JOIN IP ON INFO_SYS.IP_Adress = IP.IP 
WHERE IP.IP IS NULL;

SELECT 
  ROUND(COUNT(CASE WHEN `종류` = '네트워크장비' THEN 1 END) / COUNT(*) * 100, 1) AS 비율_퍼센트
FROM `INFO_SYS`;

